local Terrain = {size = 56}

-- Ground height at tile (i, j), or -1 where blocked or outside.
function Terrain.height(i, j)
  local row = rows[j + 1]
  if not row or i < 0 or i >= Terrain.size then return -1 end
  local c = row:sub(i + 1, i + 1)
  if c == "#" then return -1 end
  return tonumber(c)
end

return Terrain
